const LanguageContext = createContext<{ language: InterfaceLanguage, setLanguage?: (language: InterfaceLanguage) => void, t: (value: string) => string }>({ language: 'en', t: (value) => value })
function useLanguage() { return useContext(LanguageContext) }

function Logo() {
  return <div className="brand"><span className="brand-mark"><Sparkles size={16} /></span><span>synapse</span></div>
}

function Topbar({ role, setRole, lang, setLang, onBell }: { role: Role, setRole: (r: Role) => void, lang: string, setLang: (l: string) => void, onBell: (target?: Screen) => void }) {
  const { t } = useLanguage()
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const notifications = [
    ['New grade confirmed', 'Math Quiz 2 is ready to view.', 'results'], ['New feedback from Ms. Nadine', 'You have feedback on your fractions answers.', 'results'], ['Practice recommended', 'Your teacher sent a Comparing fractions set.', 'results'], ['Help request reply', 'Ms. Nadine booked an office hour for you.', 'help'],
  ] as const
  return <header className="topbar"><Logo /><div className="top-actions"><div className="role-switch"><button className={role === 'student' ? 'active' : ''} onClick={() => setRole('student')}>{t('Student')}</button><button className={role === 'teacher' ? 'active' : ''} onClick={() => setRole('teacher')}>{t('Teacher')}</button><button className={role === 'parent' ? 'active' : ''} onClick={() => setRole('parent')}>{t('Parent')}</button></div><button className="lang" onClick={() => setLang(lang === 'EN' ? 'DE' : 'EN')}><Languages size={15} /> {lang === 'EN' ? 'EN' : 'DE'} <span className="muted">| {lang === 'EN' ? 'DE' : 'EN'}</span></button><div className="notification-wrap"><button className="icon-button notification" aria-label={t('Notifications')} aria-expanded={notificationsOpen} onClick={() => role === 'student' ? setNotificationsOpen((open) => !open) : onBell()}><Bell size={19} /><b>4</b></button>{role === 'student' && notificationsOpen && <div className="notification-menu"><div className="notification-menu-head"><strong>{t('Notifications')}</strong><small>4 {t('new')}</small></div>{notifications.map(([title, message, target]) => <button className="notification-item" key={title} onClick={() => { setNotificationsOpen(false); onBell(target) }}><strong>{t(title)}</strong><span>{t(message)}</span></button>)}</div>}</div><div className="user-chip"><span className="avatar">{role === 'teacher' ? 'N' : role === 'parent' ? 'P' : 'M'}</span><span>{role === 'teacher' ? 'Ms. Nadine' : role === 'parent' ? 'Malak\'s parent' : 'Malak Adel'}</span></div></div></header>
}

function Sidebar({ screen, setScreen, role }: { screen: Screen, setScreen: (s: Screen) => void, role: Role }) {
  const { t } = useLanguage()
  const items: Array<[string, string, React.ElementType]> = role === 'teacher' ? [
    ['dashboard', 'Dashboard', LayoutDashboard], ['exams', 'Exams', FileText], ['create', 'Create exam', Plus], ['verify', 'Verify text', ScanLine], ['grades', 'Confirm grades', FileCheck2], ['gaps', 'Learning gaps', Flag], ['profile', 'Student profiles', Users], ['help', 'Help requests', MessageCircle],
  ] : [['home', 'Home', Home], ['upload', 'Upload exam', Upload], ['results', 'My results', ClipboardList], ['progress', 'My progress', Star], ['help', 'Ask for help', HelpCircle]]
  return <aside className="sidebar"><div className="view-label">{t(role === 'teacher' ? 'Teacher view' : role === 'parent' ? 'Parent view' : 'Student view')}</div>{items.map(([id, label, Icon]) => <button key={id} onClick={() => setScreen(id)} className={`side-item ${screen === id ? 'selected' : ''}`}><Icon size={18} />{t(label)}</button>)}<div className="sidebar-bottom"><button className="side-item"><Settings size={18} />{t('Settings')}</button><div className="demo-note">Frontend prototype<br /><span>Mock data only</span></div></div></aside>
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string, title: string, description?: string, action?: React.ReactNode }) { const { t } = useLanguage(); return <div className="page-header"><div><div className="eyebrow">{t(eyebrow)}</div><h1>{t(title)}</h1>{description && <p>{t(description)}</p>}</div>{action}</div> }
function StatusTracker({ current = 3 }: { current?: number }) { const { t } = useLanguage(); return <div className="tracker">{statusSteps.map((s, i) => <div className={`track-step ${i <= current ? 'done' : ''}`} key={s}><span>{i < current ? <Check size={13} /> : i + 1}</span><label>{t(s)}</label></div>)}</div> }
function Card({ children, className = '' }: { children: React.ReactNode, className?: string }) { return <section className={`card ${className}`}>{children}</section> }
function Button({ children, variant = 'primary', onClick, icon, disabled }: { children: React.ReactNode, variant?: string, onClick?: () => void, icon?: React.ReactNode, disabled?: boolean }) { const { t } = useLanguage(); return <button onClick={onClick} className={`button ${variant}`} disabled={disabled}>{icon}{typeof children === 'string' ? t(children) : children}</button> }
function Badge({ children, tone = 'neutral' }: { children: React.ReactNode, tone?: string }) { const { t } = useLanguage(); return <span className={`badge ${tone}`}>{typeof children === 'string' ? t(children) : children}</span> }

