function LoginGate({ onLogin }: { onLogin: (role: Role, language: InterfaceLanguage) => void }) {
  const [role, setRole] = useState<Role>('student'); const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [lang, setLang] = useState<'EN' | 'DE'>('EN')
  const submit = (event: React.FormEvent) => { event.preventDefault(); const account = demoCredentials[role]; if (username.trim() === account.username && password === account.password) { onLogin(role, lang === 'DE' ? 'de' : 'en') } else setError(lang === 'DE' ? `Bitte ${account.username} / ${account.password} eingeben` : `Try ${account.username} / ${account.password}`) }
  const roleCopy: Record<Role, { title: string, subtitle: string, icon: React.ElementType }> = { student: { title: lang === 'DE' ? 'Bereit für dein nächstes Lernabenteuer?' : 'Ready for your next adventure?', subtitle: lang === 'DE' ? 'Lerne, übe und entdecke deine Fortschritte.' : 'Learn, practise and see how far you have come.', icon: BookOpen }, parent: { title: lang === 'DE' ? 'Lernen gemeinsam begleiten' : 'Support learning with confidence', subtitle: lang === 'DE' ? 'Sieh die Fortschritte und Rückmeldungen zur Entwicklung deines Kindes.' : 'See your child\'s progress and teacher feedback.', icon: UserRound }, teacher: { title: lang === 'DE' ? 'Jede Antwort zählt' : 'Make every answer count', subtitle: lang === 'DE' ? 'Prüfe Arbeiten, erkenne Lernlücken und unterstütze deine Klasse.' : 'Review work, spot learning gaps and support your class.', icon: GraduationCap } }
  const selectedCopy = roleCopy[role]; const RoleIcon = selectedCopy.icon; const loginText = (english: string, german: string) => lang === 'DE' ? german : english; const roleLabel = (item: Role) => loginText(item[0].toUpperCase() + item.slice(1), item === 'student' ? 'Schüler/in' : item === 'parent' ? 'Elternteil' : 'Lehrkraft')
  return <main className="login-shell"><div className="login-panel"><div className="login-topline"><Logo /><button type="button" className="login-language" onClick={() => setLang(lang === 'EN' ? 'DE' : 'EN')} aria-label={loginText('Change interface language', 'Sprache der Benutzeroberfläche ändern')}><Languages size={15} /> {lang} <span>| {lang === 'EN' ? 'DE' : 'EN'}</span></button></div><div className="login-card"><div className="login-kicker"><Sparkles size={14} /> {loginText('Assessment workspace', 'Lern- und Prüfungsbereich')}</div><h1>{selectedCopy.title}</h1><p className="login-subtitle">{selectedCopy.subtitle}</p><div className="login-roles" role="group" aria-label={loginText('Choose your role', 'Wähle deine Rolle')}>{(['student', 'parent', 'teacher'] as Role[]).map((item) => { const ItemIcon = roleCopy[item].icon; return <button type="button" key={item} className={role === item ? 'active' : ''} aria-pressed={role === item} onClick={() => { setRole(item); setError('') }}><span className="role-icon"><ItemIcon size={21} /></span><span>{roleLabel(item)}</span><small>{item === 'student' ? loginText('Learn and practise', 'Lernen und üben') : item === 'parent' ? loginText('Follow progress', 'Fortschritte verfolgen') : loginText('Guide your class', 'Klasse begleiten')}</small></button> })}</div><div className="login-accent"><RoleIcon size={18} /><span>{role === 'student' ? loginText('Your learning space is ready.', 'Dein Lernbereich ist bereit.') : role === 'parent' ? loginText('Everything important, in one calm place.', 'Alles Wichtige an einem Ort.') : loginText('Your review workspace is ready.', 'Dein Prüfungsbereich ist bereit.')}</span></div><form className="form-card login-form" onSubmit={submit}><label>{loginText('Username', 'Benutzername')}<input value={username} onChange={(event) => setUsername(event.target.value)} placeholder={demoCredentials[role].username} autoComplete="username" /></label><label>{loginText('Password', 'Passwort')}<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder={loginText('Enter password', 'Passwort eingeben')} autoComplete="current-password" /></label>{error && <div className="alert error-alert" role="alert">{error}</div>}<Button icon={<ChevronRight size={16} />}>{loginText(`Sign in as ${role}`, `Als ${roleLabel(role)} anmelden`)}</Button><small className="login-hint">{loginText('Demo:', 'Demo-Zugang:')} {demoCredentials[role].username} / {demoCredentials[role].password}</small></form></div></div></main>
}

