function UploadFlowLegacy({ setScreen }: { setScreen: (s: Screen) => void }) {
  const [step, setStep] = useState(1); const [pages, setPages] = useState(2); const [sure, setSure] = useState<string[]>([]); const [hard, setHard] = useState(false)
  if (step === 4) return <><PageHeader eyebrow="Upload exam · Done" title="Your exam was received!" description="Nice work, Malak. Your teacher can now check your paper." /><Card className="success-card"><div className="success-mark"><Check /></div><h2>Math Quiz 3: Fractions</h2><p>Submitted on October 18, 2026 · 2 pages</p><Badge tone="warning">Uploaded</Badge><StatusTracker current={0} /><Button onClick={() => setScreen('home')} icon={<Home size={16} />}>Back to home</Button></Card></>
  const q = sure.length
  return <><PageHeader eyebrow={`Upload exam · Step ${step} of 3`} title={step === 1 ? 'Choose your exam' : step === 2 ? 'Add your exam pages' : 'How sure were you?'} description={step === 1 ? 'Choose the subject and exam you are sending.' : step === 2 ? 'Take a clear photo of each page, or choose a scan.' : `Question ${q + 1} of 3 · Tap one answer.`} /><div className="step-tabs"><span className={step >= 1 ? 'active' : ''}>1. Exam</span><span className={step >= 2 ? 'active' : ''}>2. Pages</span><span className={step >= 3 ? 'active' : ''}>3. Sure-Check</span></div>{step === 1 && <Card className="form-card"><label>Subject<select><option>Math</option><option>Science</option></select></label><label>Exam<select><option>Math Quiz 3: Fractions · October 18</option><option>Math Quiz 2 · September 28</option></select></label><div className="info-box"><ShieldCheck size={20} /><span>This exam has Sure-Check turned on. You will answer one simple question after adding your pages.</span></div><Button onClick={() => setStep(2)} icon={<ChevronRight size={16} />}>Continue</Button></Card>}{step === 2 && <><Card className="upload-zone"><div className="camera-circle"><Camera /></div><h3>Add a page</h3><p>Take a photo with your camera or choose a file from your device.</p><div className="button-row"><Button variant="secondary" onClick={() => setPages(pages + 1)} icon={<Camera size={16} />}>Take a photo</Button><Button variant="outline" onClick={() => setPages(pages + 1)} icon={<Upload size={16} />}>Choose a file</Button></div></Card><div className="page-thumbs">{Array.from({ length: pages }).map((_, i) => <div className="page-thumb" key={i}><div className="paper-placeholder"><FileText /></div><div><strong>Page {i + 1}</strong><p>{i === 1 ? 'Good quality' : 'Good quality'}</p></div><button aria-label="Delete page" onClick={() => pages > 1 && setPages(pages - 1)}><X size={16} /></button><div className="drag">⋮⋮</div></div>)}</div><div className="footer-actions"><Button variant="ghost" onClick={() => setStep(1)}>Back</Button><Button onClick={() => setStep(3)} icon={<ChevronRight size={16} />}>Continue to Sure-Check</Button></div></>}{step === 3 && q < 3 && <Card className="sure-card"><div className="question-count">Question {q + 1} / 3</div><h2>{['Which fraction is larger: 3/4 or 2/3?', 'Which fraction is equivalent to 1/2?', 'What is 5/8 + 1/8?'][q]}</h2><div className="answer-preview">Your answer: <strong>{['3/4', '2/4', '6/8'][q]}</strong></div><p className="sure-prompt">How sure were you?</p><div className="sure-options">{[['Sure', 'I knew it', '🙂'], ['Not sure', 'I was thinking', '😐'], ['Guessed', 'I guessed', '🤔']].map(([name, sub, face]) => <button key={name} onClick={() => setSure([...sure, name])} className="sure-option"><span>{face}</span><strong>{name}</strong><small>{sub}</small></button>)}</div><button className={`hard-words ${hard ? 'selected' : ''}`} onClick={() => setHard(!hard)}><Languages size={17} /> The words were hard to understand</button></Card>}{step === 3 && q >= 3 && <Card className="review-card"><div className="review-head"><Check size={20} /><div><h2>Review your answers</h2><p>Everything looks ready. You can change anything before submitting.</p></div></div><div className="review-list">{sure.map((s, i) => <div className="review-item" key={i}><span>Q{i + 1}</span><div><strong>{['3/4', '2/4', '6/8'][i]}</strong><p>{['Which fraction is larger?', 'Which fraction is equivalent?', 'What is 5/8 + 1/8?'][i]}</p></div><Badge tone={s === 'Sure' ? 'success' : 'warning'}>{s}</Badge><button className="text-button">Change</button></div>)}</div><div className="footer-actions"><Button variant="ghost" onClick={() => setStep(2)}>Back</Button><Button onClick={() => setStep(4)} icon={<Send size={16} />}>Submit exam</Button></div></Card>}</>
}

function UploadFlowContent({ setScreen, examLanguage, setExamLanguage }: { setScreen: (s: Screen) => void, examLanguage: InterfaceLanguage, setExamLanguage: (language: InterfaceLanguage) => void }) {
  type Quality = 'Good quality' | 'Blurry' | 'Too dark' | 'Cut off'
  type UploadPage = { id: number, name: string, quality: Quality, source: 'File' | 'Camera' }
  const [step, setStep] = useState(1); const [subject, setSubject] = useState('Math'); const [exam, setExam] = useState('Math Quiz 3: Fractions · October 18'); const [pages, setPages] = useState<UploadPage[]>([]); const [pending, setPending] = useState<UploadPage | null>(null); const [cameraOpen, setCameraOpen] = useState(false); const [answers, setAnswers] = useState<(string | null)[]>([null, null, null]); const [hardWords, setHardWords] = useState<string | null>(null); const [editingQuestion, setEditingQuestion] = useState(0); const [uploaded, setUploaded] = useState(false); const fileInput = useRef<HTMLInputElement>(null)
  const examTitle = examLanguage === 'de' ? 'Mathetest 3: Brüche · 18. Oktober' : 'Math Quiz 3: Fractions · October 18'; const exams = subject === 'Science' ? (examLanguage === 'de' ? ['Naturwissenschaftstest: Lebewesen · 18. Oktober', 'Materie und Materialien · 28. September'] : ['Science Quiz: Living Things · October 18', 'Matter & Materials Check · September 28']) : (examLanguage === 'de' ? ['Mathetest 3: Brüche · 18. Oktober', 'Mathetest 2 · 28. September'] : ['Math Quiz 3: Fractions · October 18', 'Math Quiz 2 · September 28']); useEffect(() => { setExam(examTitle) }, [examTitle])
  const qualityFor = (name: string): Quality => name.toLowerCase().includes('blurry') ? 'Blurry' : name.toLowerCase().includes('dark') ? 'Too dark' : name.toLowerCase().includes('cut') ? 'Cut off' : 'Good quality'
  const requestUpload = (page: UploadPage) => setPending(page)
  const confirmUpload = () => { if (!pending) return; setPages((current) => [...current, pending]); setPending(null); setUploaded(true) }
  const addDemoFile = (name: string) => requestUpload({ id: Date.now(), name, quality: qualityFor(name), source: 'File' })
  const movePage = (index: number, direction: -1 | 1) => setPages((current) => { const next = [...current]; const target = index + direction; if (target < 0 || target >= next.length) return current; [next[index], next[target]] = [next[target], next[index]]; return next })
  const questions = examLanguage === 'de' ? ['Welcher Bruch ist größer: 3/4 oder 2/3?', 'Welcher Bruch entspricht 1/2?', 'Was ist 5/8 + 1/8?'] : ['Which fraction is larger: 3/4 or 2/3?', 'Which fraction is equivalent to 1/2?', 'What is 5/8 + 1/8?']
  if (step === 4) return <><PageHeader eyebrow="Upload exam · Done" title="Your exam was received!" description="Nice work, Malak. Your teacher can now check your paper." /><Card className="success-card"><div className="success-mark"><Check /></div><h2>{exam}</h2><p>Submitted with {pages.length} pages and 3 Sure-Check answers.</p><Badge tone="success">Uploaded successfully</Badge><StatusTracker current={0} /><Button onClick={() => setScreen('home')} icon={<Home size={16} />}>Back to home</Button></Card></>
  return <><PageHeader eyebrow={`Upload exam · Step ${step} of 3`} title={step === 1 ? 'Choose your exam' : step === 2 ? 'Add your exam pages' : 'How sure were you?'} description={step === 1 ? 'Choose the subject and exam you are sending.' : step === 2 ? 'Add, inspect, and reorder every page before continuing.' : 'Answer each question with Yes or No, then review everything.'} /><div className="step-tabs"><span className={step >= 1 ? 'active' : ''}>1. Exam</span><span className={step >= 2 ? 'active' : ''}>2. Pages</span><span className={step >= 3 ? 'active' : ''}>3. Sure-Check</span></div>{step === 1 && <Card className="form-card"><label>Subject<select value={subject} onChange={(event) => { const next = event.target.value; setSubject(next); setExam(next === 'Science' ? 'Science Quiz: Living Things · October 18' : 'Math Quiz 3: Fractions · October 18') }}><option>Math</option><option>Science</option></select></label><label>Exam<select value={exam} onChange={(event) => setExam(event.target.value)}>{exams.map((item) => <option key={item}>{item}</option>)}</select></label><div className="info-box"><ShieldCheck size={20} /><span>This exam has Sure-Check turned on. You will answer three simple questions after adding your pages.</span></div><Button onClick={() => setStep(2)} icon={<ChevronRight size={16} />}>Continue</Button></Card>}{step === 2 && <><Card className="upload-zone"><div className="camera-circle"><Camera /></div><h3>Add a page</h3><p>Take a photo with your camera or choose a scan from your device.</p><div className="button-row"><Button variant="secondary" onClick={() => setCameraOpen(true)} icon={<Camera size={16} />}>Take a photo</Button><Button variant="outline" onClick={() => fileInput.current?.click()} icon={<Upload size={16} />}>Choose a file</Button><input ref={fileInput} hidden type="file" accept="image/*,.pdf" onChange={(event) => { const file = event.target.files?.[0]; if (file) requestUpload({ id: Date.now(), name: file.name, quality: qualityFor(file.name), source: 'File' }); event.currentTarget.value = '' }} /></div><div className="demo-files"><small>Demo files for quality checks</small><button onClick={() => addDemoFile('page-2-blurry.jpg')}>Blurry</button><button onClick={() => addDemoFile('page-3-too-dark.jpg')}>Too dark</button><button onClick={() => addDemoFile('page-4-cut-off.jpg')}>Cut off</button></div></Card>{uploaded && <div className="alert success-alert"><Check size={17} /> File uploaded successfully. You can still add more pages.</div>}<div className="page-thumbs">{pages.length === 0 && <Card><p className="muted">No pages added yet. Choose a demo file to preview warnings.</p></Card>}{pages.map((page, index) => <div className={`page-thumb ${page.quality !== 'Good quality' ? 'quality-warning' : ''}`} key={page.id}><div className="paper-placeholder"><FileText /></div><div className="grow"><strong>Page {index + 1} · {page.name}</strong><p>{page.quality === 'Good quality' ? 'Good quality' : `Warning: ${page.quality}. Retake this page before submitting.`}</p></div><button onClick={() => movePage(index, -1)} disabled={index === 0} aria-label="Move page up">↑</button><button onClick={() => movePage(index, 1)} disabled={index === pages.length - 1} aria-label="Move page down">↓</button><button onClick={() => setPages((current) => current.filter((item) => item.id !== page.id))} aria-label="Delete page"><X size={16} /></button></div>)}</div><div className="footer-actions"><Button variant="ghost" onClick={() => setStep(1)}>Back</Button><Button disabled={!pages.length || pages.some((page) => page.quality !== 'Good quality')} onClick={() => setStep(3)} icon={<ChevronRight size={16} />}>Continue to Sure-Check</Button></div></>}{step === 3 && <Card className="sure-card"><div className="question-count">Question {editingQuestion + 1} / 3</div><h2>{questions[editingQuestion]}</h2><div className="answer-preview">Your answer: <strong>{['3/4', '2/4', '6/8'][editingQuestion]}</strong></div><p className="sure-prompt">Were the words hard to understand?</p><div className="sure-options yes-no"><button className={answers[editingQuestion] === 'Yes' ? 'selected' : ''} onClick={() => setAnswers((current) => current.map((answer, index) => index === editingQuestion ? 'Yes' : answer))}><strong>Yes</strong><small>The wording was difficult</small></button><button className={answers[editingQuestion] === 'No' ? 'selected' : ''} onClick={() => setAnswers((current) => current.map((answer, index) => index === editingQuestion ? 'No' : answer))}><strong>No</strong><small>The wording was clear</small></button></div><div className="footer-actions"><Button variant="ghost" onClick={() => editingQuestion === 0 ? setStep(2) : setEditingQuestion(editingQuestion - 1)}>Back</Button>{editingQuestion < 2 ? <Button disabled={!answers[editingQuestion]} onClick={() => setEditingQuestion(editingQuestion + 1)} icon={<ChevronRight size={16} />}>Next question</Button> : <Button disabled={answers.some((answer) => !answer)} onClick={() => setStep(5)} icon={<ChevronRight size={16} />}>Review summary</Button>}</div></Card>}{step === 5 && <Card className="review-card"><div className="review-head"><Check size={20} /><div><h2>Review your answers</h2><p>Check every page and Sure-Check answer before submitting.</p></div></div><div className="review-list">{pages.map((page, index) => <div className="review-item" key={page.id}><span>Page {index + 1}</span><div className="grow"><strong>{page.name}</strong><p>{page.quality}</p></div><button className="text-button" onClick={() => { setStep(2); setEditingQuestion(0) }}>Change</button></div>)}{answers.map((answer, index) => <div className="review-item" key={`answer-${index}`}><span>Q{index + 1}</span><div className="grow"><strong>{questions[index]}</strong><p>Words were hard to understand</p></div><Badge tone={answer === 'No' ? 'success' : 'warning'}>{answer}</Badge><button className="text-button" onClick={() => { setEditingQuestion(index); setStep(3) }}>Change</button></div>)}</div><div className="footer-actions"><Button variant="ghost" onClick={() => setStep(3)}>Back</Button><Button onClick={() => setStep(4)} icon={<Send size={16} />}>Submit exam</Button></div></Card>}{(pending || cameraOpen) && <div className="modal-backdrop"><div className="modal"><button className="modal-close" onClick={() => { setPending(null); setCameraOpen(false) }}><X /></button>{cameraOpen ? <><div className="camera-preview"><Camera size={42} /><span>Camera preview</span><small>Prototype photo capture</small></div><h2>Use this photo?</h2><p>Review the photo before adding it to your exam.</p><div className="button-row"><Button variant="ghost" onClick={() => setCameraOpen(false)}>Retake</Button><Button onClick={() => { setCameraOpen(false); requestUpload({ id: Date.now(), name: `camera-page-${pages.length + 1}.jpg`, quality: 'Good quality', source: 'Camera' }) }} icon={<Check size={16} />}>Use photo</Button></div></> : <><h2>Upload this file?</h2><p><strong>{pending?.name}</strong> will be added as the next page.</p>{pending?.quality !== 'Good quality' && <div className="alert error-alert">This page looks {pending?.quality.toLowerCase()}. You can still upload it, but you will need to retake it before continuing.</div>}<div className="button-row"><Button variant="ghost" onClick={() => setPending(null)}>Choose another</Button><Button onClick={confirmUpload} icon={<Upload size={16} />}>Confirm upload</Button></div></>}</div></div>}</>
}

function UploadFlow({ setScreen, language }: { setScreen: (s: Screen) => void, language: InterfaceLanguage }) { return <StudentUploadFlow language={language} onHome={() => setScreen('home')} /> }

function LegacyResults({ setScreen }: { setScreen: (s: Screen) => void }) { const [done, setDone] = useState(false); return <><PageHeader eyebrow="My results" title="Math Quiz 2: Fractions" description="Confirmed by Ms. Nadine · October 12, 2026" action={<Button variant="ghost" onClick={() => setScreen('home')} icon={<Home size={16} />}>Home</Button>} /><Card className="grade-hero"><div><span className="eyebrow">Your total grade</span><div className="big-grade">8<span>/10</span></div><Badge tone="success">Grade confirmed</Badge></div><div className="teacher-note"><MessageCircle size={18} /><div><strong>Message from Ms. Nadine</strong><p>Great effort, Malak! You are getting better at finding equivalent fractions.</p></div></div></Card><Card><div className="card-title"><h2>Look at your answers</h2><Badge tone="neutral">3 questions</Badge></div><div className="answer-list"><div className="answer-row"><span className="q-mark correct">✓</span><div className="grow"><strong>Q1 · Which fraction is larger?</strong><p>Your answer: 3/4</p></div><strong>3/3</strong></div><div className="answer-row look-again"><span className="q-mark wrong">!</span><div className="grow"><strong>Q2 · Compare 2/5 and 3/5</strong><p>Your answer: 2/5 · You were sure</p><div className="hint"><strong>Let's take a second look!</strong><br />Hint: Compare the top numbers when the bottom numbers are the same.<br /><span>Correct way: 3/5 is larger because 3 is greater than 2.</span></div></div><strong>1/3</strong></div><div className="answer-row"><span className="q-mark correct">✓</span><div className="grow"><strong>Q3 · Equivalent fractions</strong><p>Your answer: 4/8</p></div><strong>4/4</strong></div></div></Card><div className="two-col"><Card><div className="card-title"><h2>My weak skills</h2></div><div className="skill-row"><span>Comparing fractions</span><Badge tone="warning">Keep practising</Badge></div><div className="skill-row"><span>Equivalent fractions</span><Badge tone="success">Getting stronger</Badge></div></Card><Card><div className="card-title"><h2>Practice to do</h2></div><label className="practice-check"><input type="checkbox" checked={done} onChange={() => setDone(!done)} /><span><strong>Fraction comparison set</strong><small>5 questions · from Ms. Nadine</small></span></label><label className="practice-check"><input type="checkbox" /><span><strong>Fractions on a number line</strong><small>4 questions · from Ms. Nadine</small></span></label></Card></div></> }

